INSERT INTO translations VALUES (1, 1, 1, 'In the name of Allah, the Most Compassionate, the Most Merciful.', '');
INSERT INTO translations VALUES (2, 1, 2, 'All praise be to Allah[1], the Lord[2] of the worlds[3],', '[1] Allah is God’s most unique name.
INSERT INTO translations VALUES (3, 1, 3, 'the Most Compassionate, the Most Merciful[4],', '[4] Ar-Rahmān and Ar-Raheem are two names of Allah: Rahmān is used only to describe Allah, while raheem might be used to describe a human as well. Rahmān carries a wider meaning - merciful to all creation. Justice is a part of this mercy. Raheem includes the concept of specialty - especially merciful to the believers. Forgiveness is a part of this mercy. In addition, Rahmān is adjectival, referring to an attribute of Allah and is part of His essence. Raheem is verbal, indicating what He does: i.e., bestowing and implementing mercy.');
INSERT INTO translations VALUES (4, 1, 4, 'Master[5] of the Day of Judgment.', '[5] Other meanings for "Mālik": Sovereign, Owner, etc.');
INSERT INTO translations VALUES (5, 1, 5, 'You alone we worship, and You alone we ask for help.', '');
INSERT INTO translations VALUES (6, 1, 6, 'Guide us to the straight path,', '');
INSERT INTO translations VALUES (7, 1, 7, 'the path of those whom You have blessed[6]; not of those who incurred Your Wrath[7], or of those who went astray[8].', '[6] The way of the Prophets and those who follow them.
INSERT INTO translations VALUES (8, 2, 1, 'Alif Lām Mīm[1].', '[1] Allah knows the meaning of these disjointed Arabic letters. This bears testimony to the inimitable nature of the Qur’an and its divine source.');
INSERT INTO translations VALUES (9, 2, 2, 'This is the Book about which there is no doubt, a guidance for the righteous[2],', '[2] Literally, "those who have taqwā," i.e., who have piety, righteousness, fear and love of Allah, and who take great care of avoiding His displeasure.');
INSERT INTO translations VALUES (11, 2, 4, 'and those who believe in what has been sent down to you [O Prophet] and in what was sent down before you[5], and in the Hereafter they believe with certainty.', '[5] i.e., the Taurāt (Torah) and the Injīl (Gospel), etc.');
INSERT INTO translations VALUES (188, 2, 181, 'If someone alters the bequest[79] after hearing it, they will bear the sin of the alteration, for Allah is All-Hearing, All-Knowing.', '[79] i.e., the will of the deceased.');
INSERT INTO translations VALUES (1236, 9, 1, '[This is] a declaration of disassociation[1] by Allah and His Messenger to those polytheists with whom you have made a treaty.', '[1] This surah, unlike all surahs of the Qur’an, is not preceded by al-basmalah (the usual opening statement).');
INSERT INTO translations VALUES (1809, 15, 7, 'Why do you not bring us the angels, if you are truthful?”', '');
INSERT INTO translations VALUES (5394, 70, 19, 'Indeed, man was created impatient:', '');
INSERT INTO translations VALUES (6226, 113, 1, 'Say, “I seek refuge with the Lord of the daybreak,', '');
INSERT INTO translations VALUES (6231, 114, 1, 'Say, “I seek refuge with the Lord of mankind,', '');
INSERT INTO translations VALUES (6232, 114, 2, 'the Sovereign of mankind[1],', '[1] i.e., the King of mankind.');
